// Generates the package's derived files. Plain Node, no dependencies. CI runs it and fails if any
// committed file differs (git diff --exit-code), so generated files can't drift from their sources.
//  1. theme-core.js -> the marked block in theme-init.js and nav.js (one reader/writer, two bundles)
//  2. hashed/theme-init.<sha8>.js + hashed/manifest.json (sha8 = first 8 hex of the file's sha256)
//     The previous release's hashed file is kept for one release so cached HTML never points at a 404.
//     manifest.previous is null for 0.1.1: 0.1.0 shipped no theme-init.
//  3. header.html and footer.html from render.mjs (reference output for the demo and tests)
import { readFileSync, writeFileSync, mkdirSync, readdirSync, unlinkSync, existsSync } from "node:fs";
import { createHash } from "node:crypto";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { renderHeader, renderFooter } from "../render.mjs";

const pkg = join(dirname(fileURLToPath(import.meta.url)), "..");
const read = (f) => readFileSync(join(pkg, f), "utf8");
const write = (f, s) => {
  if (existsSync(join(pkg, f)) && read(f) === s) return;
  writeFileSync(join(pkg, f), s);
  console.log(`wrote ${f}`);
};
const { version } = JSON.parse(read("package.json"));

// 1. Bundle theme-core.js
const BEGIN = "  // BEGIN theme-core.js (copied by scripts/build.mjs; edit theme-core.js, not this block)\n";
const END = "  // END theme-core.js\n";
const core = read("theme-core.js")
  .split("\n")
  .filter((l) => !l.trimStart().startsWith("//")) // the contract comment stays in theme-core.js; bundles stay small
  .map((l) => (l ? "  " + l : l))
  .join("\n")
  .trimEnd();
export function bundle(src) {
  const a = src.indexOf(BEGIN);
  const b = src.indexOf(END);
  if (a < 0 || b < a) throw new Error("theme-core markers not found");
  return src.slice(0, a + BEGIN.length) + core + "\n" + src.slice(b);
}
for (const f of ["theme-init.js", "nav.js"]) write(f, bundle(read(f)));

// 2. Hashed theme-init + manifest
const init = readFileSync(join(pkg, "theme-init.js"));
const sha8 = createHash("sha256").update(init).digest("hex").slice(0, 8);
const current = `theme-init.${sha8}.js`;
mkdirSync(join(pkg, "hashed"), { recursive: true });
const manifestPath = "hashed/manifest.json";
const old = existsSync(join(pkg, manifestPath)) ? JSON.parse(read(manifestPath)) : { version: null, current: null, previous: null };
// A new release rotates: last release's current becomes previous. Within a release, current is replaced.
let previous = old.version === version ? old.previous : old.current ? { version: old.version, file: old.current } : null;
if (previous && previous.file === current) previous = old.version === version ? old.previous : null;
const manifest = { version, current, previous };
write(manifestPath, JSON.stringify(manifest, null, 2) + "\n");
write(`hashed/${current}`, init.toString("utf8"));
const keep = new Set(["manifest.json", current, ...(previous ? [previous.file] : [])]);
for (const f of readdirSync(join(pkg, "hashed"))) {
  if (!keep.has(f)) {
    unlinkSync(join(pkg, "hashed", f));
    console.log(`removed hashed/${f}`);
  }
}

// 3. Reference partials
write(
  "header.html",
  `<!-- @moosematrix/tokens ${version} header partial. GENERATED by scripts/build.mjs from render.mjs + nav.json; do not edit.
     Needs tokens.css, header.css, nav.js (optional: search.html + search.js) and theme-init (first in <head>).
     Links are absolute and open in the same tab. Without JS: links work, the menu is a native <details>, search goes
     to /search/, and the page is dark. -->\n` + renderHeader({ site: "moosematrix" }),
);
write(
  "footer.html",
  `<!-- @moosematrix/tokens ${version} footer partial. GENERATED by scripts/build.mjs from render.mjs + nav.json; do not edit.
     Needs tokens.css and footer.css. Same-tab links only. -->\n` + renderFooter(),
);
